int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, d;
    cin >> n >> k >> d;

    const int MOD = 1000000007;
    vector<array<int, 2>> dp(n + 1);
    dp[0][0] = 1;

    for (int sum = 0; sum < n; ++sum) {
        for (int used = 0; used < 2; ++used) {
            for (int value = 1; value <= k && sum + value <= n; ++value) {
                int nextUsed = used || (value >= d);
                dp[sum + value][nextUsed] =
                    (dp[sum + value][nextUsed] + dp[sum][used]) % MOD;
            }
        }
    }

    cout << dp[n][1];
    return 0;
}

