#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

int n, k, d;
int dp[105][2];

int solve(int sum, bool hasD) {
    if (sum == n) return hasD;
    if (sum > n) return 0;

    int &result = dp[sum][hasD];
    if (result != -1) return result;

    result = 0;
    for (int value = 1; value <= k; ++value) {
        result = (result + solve(sum + value, hasD || value >= d)) % MOD;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k >> d;
    memset(dp, -1, sizeof(dp));

    cout << solve(0, false);
    return 0;
}

